return {["scenes"]={["s4rabbitpre"]={{["speaker"]="ringo",["portrait"]="ringon2",["line"]=1,["text"]="「操。！」",["rows"]={"「操。！」"}},{["speaker"]="seiran",["portrait"]="seiranan",["line"]=2,["text"]="「操操操。！」",["rows"]={"「操操操。！」"}},{["speaker"]="kaguya",["portrait"]="kaguya5",["line"]=3,["text"]="「这些家伙是月兔？」",["rows"]={"「这些家伙是月兔？」"}},{["speaker"]="kaguya",["portrait"]="kaguya5",["line"]=4,["text"]="「连月兔们也抵挡不了这海量的污秽吗？」",["rows"]={"「连月兔们也抵挡不了这海量的污秽吗？」"}},{["speaker"]="rabbit",["portrait"]="rabbitn2",["line"]=5,["text"]="「西八。！」",["rows"]={"「西八。！」"}},{["speaker"]="kaguya",["portrait"]="kaguya1",["line"]=6,["text"]="「这野兔魔了」",["rows"]={"「这野兔魔了」"}},{["speaker"]="kaguya",["portrait"]="kaguya21",["line"]=7,["text"]="「只好通通打醒了！」",["rows"]={"「只好通通打醒了！」"}}},["s4rabbitpost"]={{["speaker"]="ringo",["portrait"]="ringodp",["line"]=1,["text"]="「咦？」",["rows"]={"「咦？」"}},{["speaker"]="ringo",["portrait"]="ringodp",["line"]=2,["text"]="「刚才发生了什么？」",["rows"]={"「刚才发生了什么？」"}},{["speaker"]="seiran",["portrait"]="seirann2",["line"]=3,["text"]="「呜哇——好恶心的污秽味道！这究竟是哪里？」",["rows"]={"「呜哇——好恶心的污秽味道！这究竟是哪","里？」"}},{["speaker"]="kaguya",["portrait"]="kaguya1",["line"]=4,["text"]="「喂，你们两个」",["rows"]={"「喂，你们两个」"}},{["speaker"]="kaguya",["portrait"]="kaguya1",["line"]=5,["text"]="「还能想起的最后一件事是什么」",["rows"]={"「还能想起的最后一件事是什么」"}},{["speaker"]="ringo",["portrait"]="ringodp",["line"]=6,["text"]="「哇，是公主大人！」",["rows"]={"「哇，是公主大人！」"}},{["speaker"]="seiran",["portrait"]="seirann2",["line"]=7,["text"]="「已经变成了地上人的公主……要不我们假装没看见吧」",["rows"]={"「已经变成了地上人的公主……要不我们假装","没看见吧」"}},{["speaker"]="kaguya",["portrait"]="kaguya1",["line"]=8,["text"]="「你们两个叽里咕噜地说什么呢」",["rows"]={"「你们两个叽里咕噜地说什么呢」"}},{["speaker"]="seiran",["portrait"]="seirann2",["line"]=9,["text"]="「呜……没什么！」",["rows"]={"「呜……没什么！」"}},{["speaker"]="seiran",["portrait"]="seirann2",["line"]=10,["text"]="「还请您假装从没遇到过我们。」",["rows"]={"「还请您假装从没遇到过我们。」"}},{["speaker"]="ringo",["portrait"]="ringodp",["line"]=11,["text"]="「月都命令我们必须清除见到的叛徒。」",["rows"]={"「月都命令我们必须清除见到的叛徒。」"}},{["speaker"]="ringo",["portrait"]="ringodp",["line"]=12,["text"]="「但我们并不想因此和公主大人打起来……」",["rows"]={"「但我们并不想因此和公主大人打起来……」"}}},["s4pre"]={{["speaker"]="marisa",["portrait"]="marisaan",["line"]=1,["text"]="「喂！站住！」",["rows"]={"「喂！站住！」"}},{["speaker"]="kaguya",["portrait"]="kaguya5",["line"]=2,["text"]="「嗯？叫我干什么」",["rows"]={"「嗯？叫我干什么」"}},{["speaker"]="marisa",["portrait"]="marisano",["line"]=3,["text"]="「你谁啊。」",["rows"]={"「你谁啊。」"}},{["speaker"]="kaguya",["portrait"]="kaguya1",["line"]=4,["text"]="「我是前来解决异变的巫女（笑）」",["rows"]={"「我是前来解决异变的巫女（笑）」"}},{["speaker"]="marisa",["portrait"]="marisan2",["line"]=5,["text"]="「你不是竹林里那个死宅公主吗？你怎么穿着灵梦的衣服？」",["rows"]={"「你不是竹林里那个死宅公主吗？你怎么穿着","灵梦的衣服？」"}},{["speaker"]="marisa",["portrait"]="marisan2",["line"]=6,["text"]="「怎么看都像是被污秽控制了吧？」",["rows"]={"「怎么看都像是被污秽控制了吧？」"}},{["speaker"]="kaguya",["portrait"]="kaguya1",["line"]=7,["text"]="「啊哦，你听我解释。」",["rows"]={"「啊哦，你听我解释。」"}},{["speaker"]="marisa",["portrait"]="marisaan",["line"]=8,["text"]="「没有解释的必要了！」",["rows"]={"「没有解释的必要了！」"}},{["speaker"]="marisa",["portrait"]="marisaan",["line"]=9,["text"]="「让我帮你恢复清醒！看招」",["rows"]={"「让我帮你恢复清醒！看招」"}},{["speaker"]="kaguya",["portrait"]="kaguya1",["line"]=10,["text"]="「这下小伙可惨了。」",["rows"]={"「这下小伙可惨了。」"}}},["s4post"]={{["speaker"]="marisa",["portrait"]="marisadp",["line"]=1,["text"]="「我输了，怎么会……」",["rows"]={"「我输了，怎么会……」"}},{["speaker"]="kaguya",["portrait"]="kaguya5",["line"]=2,["text"]="「这下肯听我解释了吗？」",["rows"]={"「这下肯听我解释了吗？」"}},{["speaker"]="kaguya",["portrait"]="kaguya1",["line"]=3,["text"]="「我只是怕被月都的人发现行踪，所以才穿了这身衣服隐藏身份……」",["rows"]={"「我只是怕被月都的人发现行踪，所以才穿了","这身衣服隐藏身份……」"}},{["speaker"]="marisa",["portrait"]="marisadp",["line"]=4,["text"]="「原来如此，让我白高兴一场……」",["rows"]={"「原来如此，让我白高兴一场……」"}},{["speaker"]="marisa",["portrait"]="marisadp",["line"]=5,["text"]="「不过，你这身衣服确实很容易让人误会啊。」",["rows"]={"「不过，你这身衣服确实很容易让人误会啊","。」"}},{["speaker"]="kaguya",["portrait"]="kaguya5",["line"]=6,["text"]="「说起来你也是出来调查异变的吗？」",["rows"]={"「说起来你也是出来调查异变的吗？」"}},{["speaker"]="marisa",["portrait"]="marisadp",["line"]=7,["text"]="「对啊，我刚刚才结束调查，从浅间净秽山那边回来。」",["rows"]={"「对啊，我刚刚才结束调查，从浅间净秽山那","边回来。」"}},{["speaker"]="marisa",["portrait"]="marisadp",["line"]=8,["text"]="「没想到路上发现许多妖精都被一股莫名其妙的力量污染了神智。」",["rows"]={"「没想到路上发现许多妖精都被一股莫名其妙","的力量污染了神智。」"}},{["speaker"]="marisa",["portrait"]="marisadp",["line"]=9,["text"]="「我正准备继续起身前去调查呢。」",["rows"]={"「我正准备继续起身前去调查呢。」"}},{["speaker"]="kaguya",["portrait"]="kaguya5",["line"]=10,["text"]="「等等，你说的浅间净秽山是怎么回事？」",["rows"]={"「等等，你说的浅间净秽山是怎么回事？」"}},{["speaker"]="marisa",["portrait"]="marisadp",["line"]=11,["text"]="「要不你去找早苗问问吧。她好像知道很多事情。」",["rows"]={"「要不你去找早苗问问吧。她好像知道很多事","情。」"}},{["speaker"]="marisa",["portrait"]="marisadp",["line"]=12,["text"]="「我本来还打算继续问问她的。」",["rows"]={"「我本来还打算继续问问她的。」"}},{["speaker"]="marisa",["portrait"]="marisadp",["line"]=13,["text"]="「结果她突然慌慌张张地跑掉了。」",["rows"]={"「结果她突然慌慌张张地跑掉了。」"}},{["speaker"]="kaguya",["portrait"]="kaguya5",["line"]=14,["text"]="「她去了哪里？」",["rows"]={"「她去了哪里？」"}},{["speaker"]="marisa",["portrait"]="marisadp",["line"]=15,["text"]="「不知道。好像是往守矢神社的方向去了。」",["rows"]={"「不知道。好像是往守矢神社的方向去了。」"}},{["speaker"]="kaguya",["portrait"]="kaguya1",["line"]=16,["text"]="「守矢神社……」",["rows"]={"「守矢神社……」"}},{["speaker"]="marisa",["portrait"]="marisadp",["line"]=17,["text"]="「你要去找她吗？」",["rows"]={"「你要去找她吗？」"}},{["speaker"]="kaguya",["portrait"]="kaguya1",["line"]=18,["text"]="「看来只能这样了。」",["rows"]={"「看来只能这样了。」"}},{["speaker"]="marisa",["portrait"]="marisadp",["line"]=19,["text"]="「那我就先回家了。」",["rows"]={"「那我就先回家了。」"}},{["speaker"]="marisa",["portrait"]="marisadp",["line"]=20,["text"]="「输了的话，还是回去吃点心比较好。」",["rows"]={"「输了的话，还是回去吃点心比较好。」"}},{["speaker"]="kaguya",["portrait"]="kaguya1",["line"]=21,["text"]="「你倒是挺悠闲的。」",["rows"]={"「你倒是挺悠闲的。」"}},{["speaker"]="marisa",["portrait"]="marisadp",["line"]=22,["text"]="「肚子饿了嘛。」",["rows"]={"「肚子饿了嘛。」"}}},["s6open"]={{["speaker"]="kaguya",["portrait"]="kaguya1",["line"]=1,["text"]="「这里的污秽浓度已经高得惊人了。」",["rows"]={"「这里的污秽浓度已经高得惊人了。」"}},{["speaker"]="kaguya",["portrait"]="kaguya1",["line"]=2,["text"]="「看来这里就是污秽的源头。」",["rows"]={"「看来这里就是污秽的源头。」"}},{["speaker"]="kaguya",["portrait"]="kaguya5",["line"]=3,["text"]="「嗯？什么比动静……」",["rows"]={"「嗯？什么比动静……」"}}},["s6midpre"]={{["speaker"]="suwako",["portrait"]="suwakono",["line"]=1,["text"]="「……」",["rows"]={"「……」"}},{["speaker"]="kaguya",["portrait"]="kaguya1",["line"]=2,["text"]="「这作者都特么往游戏里做了点啥」",["rows"]={"「这作者都特么往游戏里做了点啥」"}},{["speaker"]="kaguya",["portrait"]="kaguya1",["line"]=3,["text"]="「根本就没有这样的生物」",["rows"]={"「根本就没有这样的生物」"}}},["s6midpost"]={{["speaker"]="kaguya",["portrait"]="kaguya5",["line"]=1,["text"]="「逃走了？」",["rows"]={"「逃走了？」"}},{["speaker"]="kaguya",["portrait"]="kaguya1",["line"]=2,["text"]="「千万别回来了」",["rows"]={"「千万别回来了」"}}},["s6pre"]={{["speaker"]="kaguya",["portrait"]="kaguya5",["line"]=1,["text"]="「早苗？」",["rows"]={"「早苗？」"}},{["speaker"]="kaguya",["portrait"]="kaguya1",["line"]=2,["text"]="「终于找到你了。」",["rows"]={"「终于找到你了。」"}},{["speaker"]="kaguya",["portrait"]="kaguya1",["line"]=3,["text"]="「魔理沙跟我说，你可能知道异变的原因。」",["rows"]={"「魔理沙跟我说，你可能知道异变的原因。」"}},{["speaker"]="fakesanae",["portrait"]="fakesanaeno",["line"]=4,["text"]="「我是早苗！」",["rows"]={"「我是早苗！」"}},{["speaker"]="kaguya",["portrait"]="kaguya21",["line"]=5,["text"]="「不好……早苗身上的污秽浓度太高，都要溢出来了！」",["rows"]={"「不好……早苗身上的污秽浓度太高，都要溢","出来了！」"}},{["speaker"]="fakesanae",["portrait"]="fakesanaeno",["line"]=6,["text"]="「我才是早苗！」",["rows"]={"「我才是早苗！」"}},{["speaker"]="kaguya",["portrait"]="kaguya1",["line"]=7,["text"]="「完蛋，又疯了一个」",["rows"]={"「完蛋，又疯了一个」"}}},["s6battle"]={{["speaker"]="suwako",["portrait"]="suwakopr",["line"]=1,["text"]="「哈哈哈哈哈哈哈哈哈！」",["rows"]={"「哈哈哈哈哈哈哈哈哈！」"}}},["s6post"]={{["speaker"]="sanae",["portrait"]="sanaedp",["line"]=1,["text"]="「啊……」",["rows"]={"「啊……」"}},{["speaker"]="sanae",["portrait"]="sanaesw",["line"]=2,["text"]="「咦？我怎么会躺在地上？」",["rows"]={"「咦？我怎么会躺在地上？」"}},{["speaker"]="kaguya",["portrait"]="kaguya1",["line"]=3,["text"]="「你终于恢复正常了。」",["rows"]={"「你终于恢复正常了。」"}},{["speaker"]="sanae",["portrait"]="sanaesw",["line"]=4,["text"]="「辉夜小姐？」",["rows"]={"「辉夜小姐？」"}},{["speaker"]="sanae",["portrait"]="sanaesw",["line"]=5,["text"]="「您为什么会在这里？」",["rows"]={"「您为什么会在这里？」"}},{["speaker"]="kaguya",["portrait"]="kaguya1",["line"]=6,["text"]="「我是被魔理沙忽悠来的。」",["rows"]={"「我是被魔理沙忽悠来的。」"}},{["speaker"]="kaguya",["portrait"]="kaguya1",["line"]=7,["text"]="「你刚才被海量的污秽控制了。」",["rows"]={"「你刚才被海量的污秽控制了。」"}},{["speaker"]="sanae",["portrait"]="sanaedp",["line"]=8,["text"]="「我记得我一直在调查浅间净秽山的事情……」",["rows"]={"「我记得我一直在调查浅间净秽山的事情…","…」"}},{["speaker"]="sanae",["portrait"]="sanaedp",["line"]=9,["text"]="「但是，我突然感受到神社正在面临巨大的威胁，就急急忙忙回来了。」",["rows"]={"「但是，我突然感受到神社正在面临巨大的威","胁，就急急忙忙回来了。」"}},{["speaker"]="sanae",["portrait"]="sanaedp",["line"]=10,["text"]="「当我刚踏进守矢神社的时候，就失去意识了……」",["rows"]={"「当我刚踏进守矢神社的时候，就失去意识","了……」"}},{["speaker"]="kaguya",["portrait"]="kaguya1",["line"]=11,["text"]="「看来你也只是一个受害人。」",["rows"]={"「看来你也只是一个受害人。」"}}},["s6kanako"]={{["speaker"]="kanako",["portrait"]="kanakono",["line"]=1,["text"]="「哎呀？没想到会有客人远道来访。」",["rows"]={"「哎呀？没想到会有客人远道来访。」"}},{["speaker"]="sanae",["portrait"]="sanaeno",["line"]=2,["text"]="「神奈子大人！」",["rows"]={"「神奈子大人！」"}},{["speaker"]="kanako",["portrait"]="kanakono",["line"]=3,["text"]="「公主，有何贵干？」",["rows"]={"「公主，有何贵干？」"}},{["speaker"]="kaguya",["portrait"]="kaguya1",["line"]=4,["text"]="「你们的神社，正源源不断地涌出海量的污秽冲击外界啊……」",["rows"]={"「你们的神社，正源源不断地涌出海量的污秽","冲击外界啊……」"}},{["speaker"]="kaguya",["portrait"]="kaguya5",["line"]=5,["text"]="「这件事情，你知道吗？」",["rows"]={"「这件事情，你知道吗？」"}},{["speaker"]="kanako",["portrait"]="kanakono",["line"]=6,["text"]="「啊？你说什么？我没有听清。麻烦重复一遍。」",["rows"]={"「啊？你说什么？我没有听清。麻烦重复一","遍。」"}},{["speaker"]="kaguya",["portrait"]="kaguya1",["line"]=7,["text"]="「明明自家的巫女都得了失心疯了，你却这样慢悠悠地现身……」",["rows"]={"「明明自家的巫女都得了失心疯了，你却这样","慢悠悠地现身……」"}},{["speaker"]="kaguya",["portrait"]="kaguya21",["line"]=8,["text"]="「恐怕你是故意的吧！」",["rows"]={"「恐怕你是故意的吧！」"}},{["speaker"]="kanako",["portrait"]="kanakono",["line"]=9,["text"]="「我只是想帮幻想乡一把。」",["rows"]={"「我只是想帮幻想乡一把。」"}},{["speaker"]="kaguya",["portrait"]="kaguya1",["line"]=10,["text"]="「果然是你这讨人嫌的家伙……霸山占林又妄图侵占山下的神社的神」",["rows"]={"「果然是你这讨人嫌的家伙……霸山占林又妄","图侵占山下的神社的神」"}},{["speaker"]="kaguya",["portrait"]="kaguya21",["line"]=11,["text"]="「就让我来惩治你！」",["rows"]={"「就让我来惩治你！」"}},{["speaker"]="kanako",["portrait"]="kanakodp",["line"]=12,["text"]="「我劝你不要不识好歹。」",["rows"]={"「我劝你不要不识好歹。」"}},{["speaker"]="kanako",["portrait"]="kanakodp",["line"]=13,["text"]="「妨碍我收集信仰的家伙，我会一个一个地连根拔起！」",["rows"]={"「妨碍我收集信仰的家伙，我会一个一个地连","根拔起！」"}}}},["art"]={["ringon2"]={["layers"]={{["file"]="art/face02bs.png",["w"]=330,["h"]=620,["cx"]=165.0,["cy"]=620},{["file"]="art/face02n2.png",["w"]=288,["h"]=186,["cx"]=139.0,["cy"]=620,["x"]=26,["y"]=0,["cw"]=262,["ch"]=186}},["scale"]=0.5806451612903226},["seiranan"]={["layers"]={{["file"]="art/face01bs.png",["w"]=520,["h"]=740,["cx"]=260.0,["cy"]=740},{["file"]="art/face01an.png",["w"]=402,["h"]=324,["cx"]=80.0,["cy"]=628,["x"]=180,["y"]=112,["cw"]=222,["ch"]=212}},["scale"]=0.4864864864864865},["rabbitn2"]={["layers"]={{["file"]="art/face02bs.png",["w"]=330,["h"]=620,["cx"]=165.0,["cy"]=620},{["file"]="art/face02n2.png",["w"]=288,["h"]=186,["cx"]=139.0,["cy"]=620,["x"]=26,["y"]=0,["cw"]=262,["ch"]=186}},["scale"]=0.5806451612903226},["ringodp"]={["layers"]={{["file"]="art/face02bs.png",["w"]=330,["h"]=620,["cx"]=165.0,["cy"]=620},{["file"]="art/face02dp.png",["w"]=288,["h"]=186,["cx"]=139.0,["cy"]=620,["x"]=26,["y"]=0,["cw"]=262,["ch"]=186}},["scale"]=0.5806451612903226},["seirann2"]={["layers"]={{["file"]="art/face01bs.png",["w"]=520,["h"]=740,["cx"]=260.0,["cy"]=740},{["file"]="art/face01n2.png",["w"]=402,["h"]=324,["cx"]=80.0,["cy"]=628,["x"]=180,["y"]=112,["cw"]=222,["ch"]=212}},["scale"]=0.4864864864864865},["marisaan"]={["layers"]={{["file"]="art/face_pl01bs.png",["w"]=700,["h"]=660,["x"]=120,["y"]=0,["cw"]=580,["ch"]=660,["cx"]=290,["cy"]=660},{["file"]="art/face_pl01an.png",["w"]=516,["h"]=284,["x"]=236,["y"]=40,["cw"]=280,["ch"]=244,["cx"]=174,["cy"]=620}},["scale"]=0.5454545454545454},["marisano"]={["layers"]={{["file"]="art/face_pl01bs